export const title = "Where to Put a Macro Pad or Number Pad on a Small Desk";
export const metaTitle = "Where to Put a Macro Pad or Numpad";
export const metaDescription = "Compare macro pad and number pad positions by actual shortcuts, mouse movement, software support, and task transitions. A research-based guide from DeskFinds.";
export const author = "Jamie Cole, Lead Product Researcher";
export const datePublished = "2026-10-28";
